package io.theficos.usuals.data.local

import androidx.room.*

// Default for unbound in-memory fixtures. Production scopes are generated by initializeLocalList.
const val LOCAL_LIST_ID = "00000000-0000-4000-8000-000000000001"

/**
 * A list on this phone. A [synced] list belongs to the signed-in account and keeps the server's last
 * projection as confirmed, with pending intents on top. [created] stays false until the server holds
 * the list. [owner] and [members] are the server's JSON, kept for the share sheet. [stale] marks a list
 * a feed reset has not returned yet.
 */
@Entity(tableName = "list_scope")
data class ListEntity(@PrimaryKey val id: String, val name: String, val archiveSource: String? = null,
    val synced: Boolean = false, val created: Boolean = false, val seq: Long = 0, val role: String? = null,
    val owner: String? = null, val members: String? = null, val stale: Boolean = false)
@Entity(tableName = "list_selection")
data class ListSelectionEntity(@PrimaryKey val singleton: Int = 1, val listId: String)
@Entity(tableName = "item_pref", primaryKeys = ["listId", "key"])
data class SharedPreferenceEntity(val listId: String, val key: String, val category: String?, val repeatEveryDays: Int?)
@Entity(tableName = "local_item_pref", primaryKeys = ["listId", "key"])
data class LocalPreferenceEntity(val listId: String, val key: String, val muted: Boolean, val snoozedUntil: Long?)
@Entity(tableName = "sync_projection")
data class ProjectionEntity(@PrimaryKey val listId: String, val confirmed: String, val optimistic: String)
/** An acknowledged intent is no longer pending; it stays so its conflict can still be reviewed. */
@Entity(tableName = "sync_outbox", primaryKeys = ["listId", "intentId"], indices = [Index("listId", "ordinal", unique = true)])
data class OutboxEntity(val listId: String, val intentId: String, val ordinal: Long, val command: String, val acknowledged: Boolean = false)
/** The account's change feed position. [resetting] spans the pages of one reset. */
@Entity(tableName = "sync_feed")
data class FeedEntity(@PrimaryKey val singleton: Int = 1, val cursor: String? = null, val resetting: Boolean = false)

/** Local review choices never reach the server or a shopping archive. */
@Entity(tableName = "conflict_dismissal", primaryKeys = ["listId", "intentId"])
data class ConflictDismissalEntity(val listId: String, val intentId: String)
